470:  * length, which is not known when this function is called. */
471: void *addReplyDeferredLen(client *c) {
472:     /* Note that we install the write event here even if the object is not
473:      * ready to be sent, since we are sure that before returning to the
474:      * event loop setDeferredAggregateLen() will be called. */
475:     if (prepareClientToWrite(c) != C_OK) return NULL;
476:     trimReplyUnusedTailSpace(c);
477:     listAddNodeTail(c->reply,NULL); /* NULL is our placeholder. */
478:     return listLast(c->reply);
479: }
